<?php session_start(); require __DIR__.'/../includes/db.php'; if(!isset($_SESSION['admin_id'])){header('Location: login.php');exit;} ?>
<?php $p=[];$error='';if($_SERVER['REQUEST_METHOD']==='POST'){ $p=$_POST;$st=mysqli_prepare($conn,"INSERT INTO products(name,price,stock,category,image,description) VALUES(?,?,?,?,?,?)");mysqli_stmt_bind_param($st,'sdisss',$p['name'],$p['price'],$p['stock'],$p['category'],$p['image'],$p['description']);if(mysqli_stmt_execute($st)){header('Location: products.php');exit;} $error='Could not add product.';} ?><!DOCTYPE html><html><head><meta charset="UTF-8"><title>Add Product</title><link rel="stylesheet" href="../css/style.css"></head><body><?php include __DIR__.'/../includes/admin_navbar.php';?><main class="admin-main"><h1>Add Product</h1><?php if($error)echo '<div class="alert-box error">'.$error.'</div>'; ?><form method="POST" class="form-card"><label>Name</label><input name="name" value="<?php echo htmlspecialchars($p['name']??'');?>" required><label>Price (BDT)</label><input type="number" name="price" min="0" step="0.01" value="<?php echo htmlspecialchars($p['price']??'');?>" required><label>Stock</label><input type="number" name="stock" min="0" value="<?php echo htmlspecialchars($p['stock']??'0');?>" required><label>Category</label><select name="category" required><?php foreach(['fashion','electronics','home','beauty'] as $c): ?><option value="<?php echo $c;?>" <?php echo (($p['category']??'')===$c?'selected':'');?>><?php echo ucfirst($c);?></option><?php endforeach;?></select><label>Image Path</label><input name="image" value="<?php echo htmlspecialchars($p['image']??'images/hero_section.png');?>" required><label>Description</label><textarea name="description"><?php echo htmlspecialchars($p['description']??'');?></textarea><button type="submit">Save Product</button></form></main></body></html>